    pipeline: ["proton-therapy", "enasidenib", "pembrolizumab"],
    openProblems: ["Late presentation: most tumours are locally advanced at diagnosis; awareness in ENT clinics and imaging AI are the response.", "No randomised trials exist for any sinonasal histology; international consortia are pooling cases.", "IDH2-mutant SNUC: prospective trials of IDH2 inhibitors.", "Visual and neurocognitive toxicity of radiotherapy: protons and reduced-margin planning."],
    targets: ["idh", "pd1"], technologies: ["imrt-igrt", "proton-therapy", "robotic-surgery", "cytotoxic-chemotherapy", "checkpoint-inhibitor"], drugs: ["cisplatin", "etoposide", "platinum-etoposide", "pembrolizumab", "nivolumab", "enasidenib"],
